css:
/* Photo row: equal-height photos, three across. */
[data-bz-node="pr-row"]{grid-template-columns:repeat(3,minmax(0,1fr));gap:clamp(16px,2.4vw,32px)}
[data-bz-node="pr-row"]>.bz-col{grid-column:auto}
[data-bz-node^="pr-img"] .bz-container,[data-bz-node^="pr-img"] .bz-figure{padding:0;margin:0;max-width:none}
[data-bz-node^="pr-img"] img{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover;border-radius:4px}
@media (max-width:640px){[data-bz-node="pr-row"]{grid-template-columns:minmax(0,1fr)}}
